"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[93293],{14571:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>o,default:()=>u,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var h=n(31085),s=n(71184);const i={sidebar_position:7,slug:"/bible/Luke/Luke_7",title:"Luke 7",hide_table_of_contents:!0},o="Luke",a={id:"bible/Luke/Luke 7",title:"Luke 7",description:"Chapter 7",source:"@site/docs/bible/Luke/Luke 7.md",sourceDirName:"bible/Luke",slug:"/bible/Luke/Luke_7",permalink:"/docs/bible/Luke/Luke_7",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Luke/Luke 7.md",tags:[],version:"current",sidebarPosition:7,frontMatter:{sidebar_position:7,slug:"/bible/Luke/Luke_7",title:"Luke 7",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Luke 6",permalink:"/docs/bible/Luke/Luke_6"},next:{title:"Luke 8",permalink:"/docs/bible/Luke/Luke_8"}},r={},d=[{value:"Chapter 7",id:"chapter-7",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"luke",children:"Luke"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-7",children:"Chapter 7"}),"\n",(0,h.jsx)(t.p,{children:"Christ heals the centurion's servant.  He raises the widow's son to life, answers the messengers sent by John and absolves the penitent sinner."}),"\n",(0,h.jsx)(n,{verse:1,children:"And when he had finished all his words in the hearing of the people, he entered into Capharnaum."}),"\n",(0,h.jsx)(n,{verse:2,children:"And the servant of a certain centurion who was dear to him, being sick, was ready to die."}),"\n",(0,h.jsx)(n,{verse:3,children:"And when he had heard of Jesus, he sent unto him the ancients of the Jews, desiring him to come and heal his servant."}),"\n",(0,h.jsx)(n,{verse:4,children:"And when they came to Jesus, they besought him earnestly, saying to him: He is worthy that thou shouldest do this for him."}),"\n",(0,h.jsx)(n,{verse:5,children:"For he loveth our nation: and he hath built us a synagogue."}),"\n",(0,h.jsx)(n,{verse:6,children:"And Jesus went with them. And when he was now not far from the house, the centurion sent his friends to him, saying: Lord, trouble not thyself; for I am not worthy that thou shouldst enter under my roof."}),"\n",(0,h.jsx)(n,{verse:7,children:"For which cause neither did I think myself worthy to come to thee: but say the word, and my servant shall be healed."}),"\n",(0,h.jsx)(n,{verse:8,children:"For I also am a man subject to authority, having under me soldiers: and I say to one, Go, and he goeth: and to another, Come, and he cometh; and to my servant, Do this, and he doth it."}),"\n",(0,h.jsx)(n,{verse:9,children:"Which Jesus hearing, marvelled: and turning about to the multitude that followed him, he said: Amen I say to you, I have not found so great faith, not even in Israel."}),"\n",(0,h.jsx)(n,{verse:10,children:"And they who were sent, being returned to the house, found the servant whole who had been sick."}),"\n",(0,h.jsx)(n,{verse:11,children:"And it came to pass afterwards that he went into a city that is called Naim: and there went with him his disciples and a great multitude."}),"\n",(0,h.jsx)(n,{verse:12,children:"And when he came nigh to the gate of the city, behold a dead man was carried out, the only son of his mother: and she was a widow. And a great multitude of the city was with her."}),"\n",(0,h.jsx)(n,{verse:13,children:"Whom when the Lord had seen, being moved with mercy towards her, he said to her: Weep not."}),"\n",(0,h.jsx)(n,{verse:14,children:"And he came near and touched the bier. And they that carried it stood still. And he said: Young man, I say to thee, arise."}),"\n",(0,h.jsx)(n,{verse:15,children:"And he that was dead sat up and begun to speak. And he gave him to his mother."}),"\n",(0,h.jsx)(n,{verse:16,children:"And there came a fear upon them all: and they glorified God saying: A great prophet is risen up among us: and, God hath visited his people."}),"\n",(0,h.jsx)(n,{verse:17,children:"And this rumour of him went forth throughout all Judea and throughout all the country round about."}),"\n",(0,h.jsx)(n,{verse:18,children:"And John's disciples told him of all these things."}),"\n",(0,h.jsx)(n,{verse:19,children:"And John called to him two of his disciples and sent them to Jesus, saying: Art thou he that art to come? Or look we for another?"}),"\n",(0,h.jsx)(n,{verse:20,children:"And when the men were come unto him, they said: John the Baptist hath sent us to thee, saying: Art thou he that art to come? Or look we for another?"}),"\n",(0,h.jsx)(n,{verse:21,children:"(And in that same hour, he cured many of their diseases and hurts and evil spirits: and to many that were blind he gave sight.)"}),"\n",(0,h.jsx)(n,{verse:22,children:"And answering, he said to them: Go and relate to John what you have heard and seen: the blind see, the lame walk, the lepers are made clean, the deaf hear, the dead rise again, to the poor the gospel is preached."}),"\n",(0,h.jsx)(n,{verse:23,children:"And blessed is he whosoever shall not be scandalized in me."}),"\n",(0,h.jsx)(n,{verse:24,children:"And when the messengers of John were departed, he began to speak to the multitudes concerning John. What went ye out into the desert to see? A reed shaken with the wind?"}),"\n",(0,h.jsx)(n,{verse:25,children:"But what went you out to see? A man clothed in soft garments? Behold they that are in costly apparel and live delicately are in the houses of kings."}),"\n",(0,h.jsx)(n,{verse:26,children:"But what went you out to see? A prophet? Yea, I say to you, and more than a prophet."}),"\n",(0,h.jsx)(n,{verse:27,children:"This is he of whom it is written: Behold I send my angel before thy face, who shall prepare thy way before thee."}),"\n",(0,h.jsx)(n,{verse:28,children:"For I say to you: Amongst those that are born of men, there is not a greater prophet than John the Baptist. But he that is the lesser in the kingdom of God is greater than he."}),"\n",(0,h.jsx)(n,{verse:29,children:"And all the people hearing, and the publicans, justified God, being baptized with John's baptism."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: Justified God...that is, praised the justice of God, feared and worshipped God, as just and merciful."})}),"\n",(0,h.jsx)(n,{verse:30,children:"But the Pharisees and the lawyers despised the counsel of God against themselves, being not baptized by him."}),"\n",(0,h.jsx)(n,{verse:31,children:"And the Lord said: Whereunto then shall I liken the men of this generation? And to what are they like?"}),"\n",(0,h.jsx)(n,{verse:32,children:"They are like to children sitting in the marketplace and speaking one to another and saying: We have piped to you, and you have not danced: we have mourned, and you have not wept."}),"\n",(0,h.jsx)(n,{verse:33,children:"For John the Baptist came neither eating bread nor drinking wine. And you say: He hath a devil."}),"\n",(0,h.jsx)(n,{verse:34,children:"The Son of man is come eating and drinking. And you say: Behold a man that is a glutton and a drinker of wine, a friend of publicans and sinners."}),"\n",(0,h.jsx)(n,{verse:35,children:"And wisdom is justified by all her children."}),"\n",(0,h.jsx)(n,{verse:36,children:"And one of the Pharisees desired him to eat with him. And he went into the house of the Pharisee and sat down to meat. One of the Pharisees: that is, Simon."}),"\n",(0,h.jsx)(n,{verse:37,children:"And behold a woman that was in the city, a sinner, when she knew that he sat at meat in the Pharisee's house, brought an alabaster box of ointment."}),"\n",(0,h.jsx)(n,{verse:38,children:"And standing behind at his feet. she began to wash his feet with tears and wiped them with the hairs of her head and kissed his feet and anointed them with the ointment."}),"\n",(0,h.jsx)(n,{verse:39,children:"And the Pharisee, who had invited him, seeing it, spoke within himself, saying: This man, if he were if a prophet, would know surely who and what manner of woman this is that toucheth him, that she is a sinner."}),"\n",(0,h.jsx)(n,{verse:40,children:"And Jesus answering, said to him: Simon, I have somewhat to say to thee. But he said: Master, say it."}),"\n",(0,h.jsx)(n,{verse:41,children:"A certain creditor had two debtors: the one owed five hundred pence and the other fifty."}),"\n",(0,h.jsx)(n,{verse:42,children:"And whereas they had not wherewith to pay, he forgave them both. Which therefore of the two loveth him most?"}),"\n",(0,h.jsx)(n,{verse:43,children:"Simon answering, said: I suppose that he to whom he forgave most. And he said to him: Thou hast judged rightly."}),"\n",(0,h.jsx)(n,{verse:44,children:"And turning to the woman, he said unto Simon: Dost thou see this woman? I entered into thy house: thou gavest me no water for my feet. But she with tears hath washed my feet; and with her hairs hath wiped them."}),"\n",(0,h.jsx)(n,{verse:45,children:"Thou gavest me no kiss. But she, since she cane in, hath not ceased to kiss my feet."}),"\n",(0,h.jsx)(n,{verse:46,children:"My head with oil thou didst not anoint. But she with ointment hath anointed my feet."}),"\n",(0,h.jsx)(n,{verse:47,children:"Wherefore, I say to thee: Many sins are forgiven her, because she hath loved much. But to whom less is forgiven, he loveth less."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: Many sins are forgiven her, because she hath loved much...In the scripture an effect sometimes seems attributed to one only cause, when there are divers other concurring dispositions; for the sins of this woman, in this verse, are said to be forgiven, because she loved much: but (ver. 50) Christ tells her, Thy faith hath made thee safe. Hence in a true conversion are joined faith, hope, love, sorrow for sin, and other pious dispositions."})}),"\n",(0,h.jsx)(n,{verse:48,children:"And he said to her: Thy sins are forgiven thee."}),"\n",(0,h.jsx)(n,{verse:49,children:"And they that sat at meat with him began to say within themselves: Who is this that forgiveth sins also?"}),"\n",(0,h.jsx)(n,{verse:50,children:"And he said to the woman: Thy faith hath made thee safe. Go in peace."})]})}function u(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>a});var h=n(14041);const s={},i=h.createContext(s);function o(e){const t=h.useContext(i);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),h.createElement(i.Provider,{value:t},e.children)}}}]);